import {openMicroModeling} from './micro-modeling-dialog.js';
import {createMolecule} from './molecule.js';
import {reflowPipe,createPipeSegment} from './application-models.js';
import {structureProperty,storePropertyValues,renderMaterialProperties,prepareMaterialProperties,materialPropertyOptions,mountMaterialPropertyEditor,materialPropertyIssues} from './material-properties.js';
import {primitiveTypes,validatePrimitive} from './primitives.js';
import {esc} from './model.js';
import {icon} from '../../shared/icons.js';
import {macroMaterials,macroSettings,materialLibrary,validateMaterials,validateMacroSettings,modelStructures,assignStructureMaterial} from './macro-state.js';
const labels={geometry:'几何设置',materials:'材料管理',mesh:'网格设置',physics:'物理场与边界',study:'研究设置'};
export function macroToolbar(pipe=false){return `<div class="macro-tools" role="toolbar" aria-label="宏观建模快捷工具">${Object.entries(labels).filter(([id])=>['geometry','materials'].includes(id)).map(([id,label])=>`<button type="button" data-macro-tool="${id}">${icon(id==='materials'?'molecule':id==='geometry'?'grid':id==='study'?'flask':'flow')}${label}</button>`).join('')}<span class="macro-tools-divider"></span><button type="button" data-model-view="clear">清除选择</button><button type="button" data-model-view="reset">${icon('grid')}适应模型</button><label>标准视图<select aria-label="标准视图" data-standard-view><option value="iso">等轴测</option><option value="xy">XY 平面</option><option value="yz">YZ 平面</option><option value="xz">XZ 平面</option></select></label>${pipe?'':'<button type="button" data-model-view="transparent" aria-pressed="true">透明基体</button>'}<button type="button" data-model-upload-preview title="上传工程模型文件（示意）">${icon('upload')}上传模型</button></div>`;}
const number=(key,label,v,unit='')=>`<label class="macro-field"><span>${label}</span><div><input type="number" step="any" name="${key}" value="${esc(v)}" required>${unit?`<small>${unit}</small>`:''}</div></label>`;
const select=(key,label,value,options)=>`<label class="macro-field"><span>${label}</span><select name="${key}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;
export function openMacroSettings(kind,n,{openDialog,onSave}){
 const draft=structuredClone(macroSettings(n)),unit=draft.unit;
 let fields='';
 if(kind==='geometry')fields=select('unit','长度单位',unit,['mm','μm','nm'])+number('length','X 向长度',draft.length,unit)+number('width','Y 向宽度',draft.width,unit)+number('height','Z 向高度',draft.height,unit)+'<p class="macro-note">设置模型参考尺寸；通过建模视图中的几何体工具创建和编辑具体几何。</p>';
 if(kind==='mesh')fields=number('meshSize','最大单元尺寸',draft.meshSize,unit)+select('meshOrder','单元阶次',draft.meshOrder,['一阶','二阶'])+'<p class="macro-note">保存网格划分参数；尚未接入真实网格划分服务。</p>';
 if(kind==='physics')fields=select('physics','物理场',draft.physics,['稳态导热'])+select('hotFace','热端表面',draft.hotFace,['X+','X−','Y+','Y−','Z+','Z−'])+number('hot','热端温度',draft.hot,'°C')+select('coldFace','冷端表面',draft.coldFace,['X+','X−','Y+','Y−','Z+','Z−'])+number('cold','冷端温度',draft.cold,'°C')+'<p class="macro-note">其余外表面默认绝热。当前支持导热设置演示。</p>';
 if(kind==='study')fields=select('study','研究类型',draft.study,['稳态'])+number('tolerance','相对收敛容差',draft.tolerance)+'<p class="macro-note">计算资源与物性算法在工作流相应节点中配置。</p>';
 const d=openDialog(`<form class="dialog-form macro-settings"><h2>${labels[kind]}</h2><p class="macro-note">${esc(n.params.modelName)} · 宏观模型</p><div class="macro-fields">${fields}</div><p class="macro-error" role="alert"></p><div class="dialog-actions"><button type="button" class="btn" data-dialog-close>取消</button><button class="btn primary">应用设置</button></div></form>`);d.classList.add('macro-settings-dialog');
 d.querySelector('form').onsubmit=e=>{e.preventDefault();for(const input of d.querySelectorAll('[name]'))draft[input.name]=input.type==='number'?Number(input.value):input.value;const error=validateMacroSettings(draft);if(error){d.querySelector('.macro-error').textContent=error;return;}onSave(draft,kind);d.close();};
}
export function openMaterials(n,{openDialog,onSave,initialId,addStructure=false,getMicroModel,canEditMicroModel=()=>true}){
 const draft=structuredClone(modelStructures(n).filter(m=>m.region!=='none'));let selected=initialId||draft[0]?.id,sequence=Date.now();
 function createStructure(){let index=1;while(draft.some(m=>m.name==='材料'+index))index++;const isBase=!draft.some(m=>m.region==='matrix');const name=isBase?'基底':'材料'+index,m={id:'structure-'+sequence++,name,structureName:name,region:isBase?'matrix':'filler',shape:index===1?'sphere':'platelet',color:isBase?'#a8bdd7':index===1?'#b394dc':'#8daebc',density:1000,conductivity:1,material:null};prepareMaterialProperties(m,n);draft.push(m);selected=m.id;}
 if(addStructure)createStructure();
 for(const material of draft)prepareMaterialProperties(material,n);
 const d=openDialog(`<form class="dialog-form macro-material-form"><h2>材料管理</h2><p class="macro-note">先定义模型中的结构，再为每个结构指定材料库中的材料。形貌属于结构设置。</p><div class="material-manager structure-manager"><section><h3>模型结构 <small data-material-total></small></h3><div data-current-materials></div><button type="button" class="btn" data-add-structure>${icon('plus')}添加结构</button><p class="macro-note">基底、材料1、材料2是模型中的结构。多个结构可以引用同一份材料库数据。</p></section><section><h3>结构设置</h3><div data-material-properties></div><section class="material-key-properties"><h3>关键物性参数</h3><div data-property-config></div></section></section></div><p class="macro-error" role="alert"></p><div class="dialog-actions"><button type="button" class="btn" data-dialog-close>取消</button><button class="btn primary">应用结构与材料</button></div></form>`);d.classList.add('material-manager-dialog');if(n.params.materialScope==='whole-model'){d.querySelector('h2').textContent='流体材料设置';d.querySelector('.macro-note').textContent='四段管路共用一种流体材料，统一设置材料与关键物性计算参数。';d.querySelector('.structure-manager>section>h3').innerHTML='流体材料 <small data-material-total></small>';d.querySelector('.structure-manager>section>.macro-note').textContent='管段仅用于几何尺寸编辑，不分别分配材料。';d.querySelector('.structure-manager>section:nth-child(2)>h3').textContent='材料设置';}if(n.params.geometryKind==='pipe')d.querySelector('[data-add-structure]').style.display='none';
 const error=msg=>d.querySelector('.macro-error').textContent=msg;
 const propertyEditor=mountMaterialPropertyEditor(d.querySelector('[data-property-config]'),()=>draft.find(m=>m.id===selected),n.params.case);
 function collect(){const m=draft.find(m=>m.id===selected);if(!m)return;for(const input of d.querySelectorAll('[data-material-field]'))m[input.dataset.materialField]=input.type==='number'?Number(input.value):input.value;m.structureName=m.name;collectProperties(m);}
 function collectProperties(m){propertyEditor.collect();}
 function render(){d.querySelector('[data-material-total]').textContent=draft.length+(n.params.materialScope==='whole-model'?' 种':' 个');d.querySelector('[data-current-materials]').innerHTML=draft.map(m=>`<div class="material-with-micro"><button type="button" data-pick-material="${m.id}" aria-pressed="${m.id===selected}"><i style="background:${m.color}"></i><span>${esc(m.name)}<small>${esc(m.material?.name||'未指定材料')}</small></span><small>${m.shape==='whole'?'整体':m.region==='domain'?(m.shape==='cone'?'圆锥段':'圆柱段'):m.region==='matrix'?'基底':m.shape==='platelet'?'片状':'球状'}</small></button><button type="button" class="material-micro-entry" data-material-micro="${m.id}" aria-label="${esc(m.name)}的微观建模">${icon('molecule')}微观建模${icon('chevron')}</button></div>`).join('');const m=draft.find(m=>m.id===selected);d.querySelector('[data-material-properties]').innerHTML=m?`<label class="macro-field"><span>${n.params.materialScope==='whole-model'?'材料名称':'结构名称'}</span><input data-material-field="name" value="${esc(m.name)}" required maxlength="40"></label><div class="material-property-row"><label class="macro-field"><span>显示颜色</span><input type="color" data-material-field="color" value="${m.color}"></label>${n.params.materialScope==='whole-model'?'':`<label class="macro-field"><span>结构形貌</span>${m.region==='domain'?`<input value="${m.shape==='cone'?'圆锥过渡段':'圆柱段'}" readonly>`:m.region==='matrix'?'<input value="基底（长方体）" readonly>':`<select data-material-field="shape"><option value="sphere" ${m.shape!=='platelet'?'selected':''}>球状</option><option value="platelet" ${m.shape==='platelet'?'selected':''}>片状</option></select>`}</label>`}</div><label class="macro-field"><span>对应材料（材料库）</span><select data-library-select><option value="">请选择材料库数据</option>${m.material&&!materialLibrary.some(item=>item.id===m.material.libraryId)?`<option value="${esc(m.material.libraryId)}" selected>${esc(m.material.name)} · 原模型材料</option>`:''}${materialLibrary.map(item=>`<option value="${item.id}" ${m.material?.libraryId===item.id?'selected':''}>${esc(item.name)} · ${esc(item.category)}</option>`).join('')}</select></label><div class="assigned-material-card"><span>已引用材料数据</span><strong>${esc(m.material?.name||'尚未选择')}</strong><small>${m.material?'材料库引用 · '+esc(m.material.moleculeId):'请在下方选择材料库中的分子数据'}</small>${m.material?`<dl><div><dt>密度</dt><dd>${esc(m.material.density)} kg/m³</dd></div><div><dt>热导率</dt><dd>未知</dd></div></dl><p class="macro-note">分子结构与物性为原型示例，不代表真实材料数据。${n.params.materialScope==='whole-model'?'所有管段统一使用当前材料。':'修改本结构的形貌不会修改材料库。'}</p>`:''}</div>${['matrix','domain'].includes(m.region)?'':'<button type="button" class="text-btn" data-remove-structure>删除结构</button>'}`:'<p class="macro-note">点击添加结构开始配置。</p>';propertyEditor.render();}
 d.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.materialMicro){collect();selected=b.dataset.materialMicro;render();const m=draft.find(m=>m.id===selected);if(!m)return;openMicroModeling(openDialog,m.molecule||getMicroModel?.(m)||m.material?.molecule||createMolecule(),{title:m.name+' · 微观建模',materialName:m.material?.name||m.name,readOnly:!canEditMicroModel(m.id),onApply:next=>{m.molecule=next;render();}});return;}if(b.dataset.pickMaterial){collect();selected=b.dataset.pickMaterial;render();}if(b.hasAttribute('data-add-structure')){collect();createStructure();error('');render();}if(b.hasAttribute('data-remove-structure')){draft.splice(draft.findIndex(m=>m.id===selected),1);selected=draft[0]?.id;render();}});
 d.querySelector('[data-material-properties]').addEventListener('change',e=>{collect();error('');if(e.target.hasAttribute('data-library-select')){if(e.target.value)assignStructureMaterial(draft.find(m=>m.id===selected),e.target.value);else draft.find(m=>m.id===selected).material=null;}render();});d.querySelector('form').onsubmit=e=>{e.preventDefault();collect();const propertyError=draft.flatMap(m=>materialPropertyIssues(m,n.params.case))[0];if(propertyError){error(propertyError.join('：'));return;}const problem=validateMaterials(draft);if(problem){error(problem);return;}onSave(draft);d.close();};render();
}

export function openPrimitive(type,n,{openDialog,onSave,pipeSegment=false},id){
 const settings=structuredClone(macroSettings(n)),existing=settings.primitives?.find(p=>p.id===id),size=Math.min(settings.length,settings.width,settings.height)*.4;
 const draft=existing||(pipeSegment?createPipeSegment(settings):null)||{id:'geometry-'+Date.now(),type,name:primitiveTypes[type],length:size,width:size,height:size,radius:size/2,tubeRadius:size/6,x:n.params.blankGeometry&&!settings.primitives?.length?0:settings.length*.8,y:0,z:0};
 const extrusionSegment=draft.pipeSegment&&n.params.case==='extrusion';
 if(extrusionSegment){draft.crossSection??='circle';draft.endRadius??=draft.radius;draft.inletLength??=draft.radius*2;draft.inletWidth??=draft.radius*2;draft.outletLength??=draft.endRadius*2;draft.outletWidth??=draft.endRadius*2;}
 const sectionFields=()=>number('height','管段长度',draft.height,settings.unit)+`<label class="macro-field"><span>截面形状</span><select name="crossSection"><option value="circle" ${draft.crossSection!=='rectangle'?'selected':''}>圆形</option><option value="rectangle" ${draft.crossSection==='rectangle'?'selected':''}>方形</option></select></label>`+(draft.crossSection==='rectangle'?number('inletLength','入口长',draft.inletLength,settings.unit)+number('inletWidth','入口宽',draft.inletWidth,settings.unit)+number('outletLength','出口长',draft.outletLength,settings.unit)+number('outletWidth','出口宽',draft.outletWidth,settings.unit):number('radius','入口半径',draft.radius,settings.unit)+number('endRadius','出口半径',draft.endRadius,settings.unit));
 const dimensions=extrusionSegment?sectionFields():draft.pipeSegment?number('height','管段长度',draft.height,settings.unit)+number('radius',draft.type==='cone'?'入口半径':'半径',draft.radius,settings.unit)+(draft.type==='cone'?number('endRadius','出口半径',draft.endRadius,settings.unit):''):['block','ellipsoid'].includes(type)?number('length','长度',draft.length,settings.unit)+number('width','宽度',draft.width,settings.unit)+number('height','高度',draft.height,settings.unit):number('radius',type==='torus'?'主半径':'半径',draft.radius,settings.unit)+(type==='torus'?number('tubeRadius','管半径',draft.tubeRadius,settings.unit):['cylinder','cone'].includes(type)?number('height','高度',draft.height,settings.unit):'');
 const d=openDialog(`<form class="dialog-form macro-settings"><h2>${extrusionSegment?(existing?'编辑管段':'添加管段'):(existing?'编辑':'创建')+primitiveTypes[type]}</h2><label class="macro-field"><span>几何体名称</span><input name="name" value="${esc(draft.name)}" required maxlength="40"></label>${extrusionSegment&&!existing?`<label class="macro-field"><span>添加位置</span><select name="order">${Array.from({length:settings.primitives.filter(p=>p.pipeSegment).length+1},(_,i)=>`<option value="${i}" ${i===draft.order?'selected':''}>${i===0?'管路最前端':i===draft.order?'管路末端':'第'+(i+1)+'段之前'}</option>`).join('')}</select></label>`:''}<div class="macro-fields" data-primitive-dimensions>${dimensions}</div>${draft.pipeSegment?'<p class="macro-note">管段沿 X 方向连续排列；同类截面的相邻接口尺寸自动同步，不同截面分别保留尺寸。</p>':`<h3>中心位置</h3><div class="primitive-position">${['x','y','z'].map(k=>number(k,k.toUpperCase(),draft[k],settings.unit)).join('')}</div>`}${draft.pipeSegment?'':'<p class="macro-note">创建独立几何体，支持尺寸和位置编辑；当前显示为实体示意，不执行布尔运算。</p>'}<p class="macro-error" role="alert"></p><div class="dialog-actions">${existing?'<button type="button" class="btn" data-remove-primitive>删除几何体</button>':''}<button type="button" class="btn" data-dialog-close>取消</button><button class="btn primary">${existing?'保存几何体':'创建几何体'}</button></div></form>`);d.classList.add('macro-settings-dialog');if(extrusionSegment)d.classList.add('pipe-segment-dialog');
 const collectPrimitive=()=>{for(const input of d.querySelectorAll('[name]'))draft[input.name]=input.type==='number'||input.name==='order'?Number(input.value):input.value;};
 d.addEventListener('change',e=>{if(!e.target.matches('[name=crossSection]'))return;collectPrimitive();d.querySelector('[data-primitive-dimensions]').innerHTML=sectionFields();});
 d.querySelector('form').onsubmit=e=>{e.preventDefault();collectPrimitive();if(extrusionSegment)draft.type=draft.crossSection==='rectangle'?(draft.inletLength===draft.outletLength&&draft.inletWidth===draft.outletWidth?'cylinder':'cone'):(draft.radius===draft.endRadius?'cylinder':'cone');const error=validatePrimitive(draft);if(error){d.querySelector('.macro-error').textContent=error;return;}const index=settings.primitives?.findIndex(p=>p.id===draft.id)??-1;if(index>=0)settings.primitives[index]=draft;else{if(extrusionSegment)for(const part of settings.primitives.filter(p=>p.pipeSegment))if(part.order>=draft.order)part.order++;settings.primitives=[...(settings.primitives||[]),draft];}if(draft.pipeSegment)reflowPipe(settings,draft.id);onSave(settings);d.close();};
 const remove=d.querySelector('[data-remove-primitive]');if(remove)remove.onclick=()=>{settings.primitives=settings.primitives.filter(p=>p.id!==id);if(draft.pipeSegment)reflowPipe(settings);onSave(settings);d.close();};
}
